            return RainwaterProfile.totalTrapped(heights);
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        int[] classic = {0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1};
        check("waterPerColumn(classic)", "[0, 0, 1, 0, 1, 2, 1, 0, 0, 1, 0, 0]", perColumn(classic));
        check("totalTrapped(classic)", 6L, total(classic));
        check("classic input unchanged", "[0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1]", java.util.Arrays.toString(classic));
        check("totalTrapped({4,2,0,3,2,5})", 9L, total(new int[] {4, 2, 0, 3, 2, 5}));
        check("waterPerColumn({5,0,5})", "[0, 5, 0]", perColumn(new int[] {5, 0, 5}));
