public class RainwaterProfile {

    public static int[] waterPerColumn(int[] heights) {
        if (heights == null) {
            return new int[0];
        }
        int n = heights.length;
        int[] water = new int[n];
        if (n < 3) {
            return water;
        }
        int[] tallestLeft = new int[n];
        int[] tallestRight = new int[n];
        tallestLeft[0] = heights[0];
        for (int i = 1; i < n; i++) {
            tallestLeft[i] = Math.max(tallestLeft[i - 1], heights[i]);
        }
        tallestRight[n - 1] = heights[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            tallestRight[i] = Math.max(tallestRight[i + 1], heights[i]);
        }
        for (int i = 0; i < n; i++) {
            int depth = Math.min(tallestLeft[i], tallestRight[i]) - heights[i];
            water[i] = Math.max(depth, 0);
        }
        return water;
    }

    public static long totalTrapped(int[] heights) {
        long total = 0;
        for (int depth : waterPerColumn(heights)) {
            total += depth;
        }
        return total;
    }
}
